function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 65535)) return 'Each value is an integer from 0 to 65535 (below 2^16).';
  return null;
}

