function countTriplets(nums) {
  let full = 0;
  for (const value of nums) full |= value;
  const pairs = new Array(full + 1).fill(0);
  for (const first of nums) {
    for (const second of nums) {
      pairs[first & second]++;
    }
  }

  let count = 0;
  for (const third of nums) {
    const free = full & ~third;
    for (let mask = free; ; mask = (mask - 1) & free) {
      count += pairs[mask];
      if (mask === 0) break;
    }
  }
  return count;
}

