function generate(rand, size) {
  const n = size === 'large' ? 900 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 8);
  const style = rand();
  if (style < 0.25) {
    // Values over a few low bits, so ANDs often collide and counts are large.
    const width = 1 + Math.floor(rand() * 4);
    return [Array.from({ length: n }, () => Math.floor(rand() * (1 << width)))];
  }
  if (style < 0.4) {
    // One value repeated, sometimes with a zero or a full mask mixed in.
    const value = Math.floor(rand() * 65536);
    return [Array.from({ length: n }, () => (rand() < 0.15 ? (rand() < 0.5 ? 0 : 65535) : value))];
  }
  // Each bit set with probability p: sparse values give many zero ANDs, dense ones few.
  const p = 0.1 + rand() * 0.8;
  return [Array.from({ length: n }, () => {
    let value = 0;
    for (let bit = 0; bit < 16; bit++) if (rand() < p) value |= 1 << bit;
    return value;
  })];
}
